    ["name.statuses.position"] = "Above the name, over the mastery stars where it has them, or below it, under the line a checked monster's details are written on while they are shown.",
    ["name.statuses.preview"] = "Puts the first few ticked statuses over every name that is shown, whatever it is really under, to see how the row looks. Not kept: it is off again when the addon is loaded.",
    ["name.statuses.search"] = "Part of a status's name, or its number. Only a ticked status is drawn over a name.",
